import {linearChallenges} from './linear-pathway-generator.mjs';
import {linearLessons,linearPages,linearRecommendations} from './linear-pathway-content.mjs';
import {linearView,linearValue,formatLinearNumber,parseLinearNumber,startLinear,setLinearPage,setLinearX,setLinearField,showLinearHelp,checkLinear,skipLinear,setLinearNote,setLinearRecommendation,keepLinear,validLinearWork,linearSuggestion,linearGeneratedVisits,createLinearInvestigation,removeLinearInvestigation} from './linear-pathway-core.mjs';
import {stopSpeech} from './play-media.mjs';
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(attrs,text,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(text)}</button>`;
export const linearEntry=()=>'<aside class="linear-entry"><a href="#learn/math">Signed rates and linear equations</a><p>Explore six open lessons: across zero, fractional rates, rules, equal steps, fee plans and a new context.</p></aside>';
function graph(w){const m=w.source.model,X=x=>42+44*x,Y=q=>240-(q.n/q.d+6)*9,partner=m.comparison?{...m,...m.comparison}:null;return `<figure class="linear-graph"><svg viewBox="0 0 350 295" role="img" aria-label="${esc(m.title)}. Current input ${w.x} ${esc(m.xUnit)}, output ${formatLinearNumber(linearValue(m,w.x))} ${esc(m.yUnit)}. Exact values follow in the table."><title>Input and output on fixed axes</title><desc>Horizontal axis: input from 0 to 6. Vertical axis: output from minus 6 to 16. Axis units and scales differ. Read numerical changes rather than visual angles.</desc>${[-6,-4,-2,0,2,4,6,8,10,12,14,16].map(n=>`<path d="M42 ${Y({n,d:1})}H306" stroke="#c7d6cf"/><text x="34" y="${Y({n,d:1})+5}" text-anchor="end">${n}</text>`).join('')}<path d="M42 42V240M42 ${Y({n:0,d:1})}H316" fill="none" stroke="#294e54" stroke-width="2"/>${Array.from({length:7},(_,x)=>`<text x="${X(x)}" y="264" text-anchor="middle">${x}</text>`).join('')}<text x="42" y="22">y · ${esc(m.yUnit)}</text><text x="42" y="286">x · ${esc(m.xUnit)}</text>${[m,...(partner?[partner]:[])].map((s,i)=>`<path d="M${X(0)} ${Y(linearValue(s,0))}L${X(6)} ${Y(linearValue(s,6))}" stroke="${i?'#994f32':'#245d6b'}" stroke-width="3" ${i?'stroke-dasharray="7 5"':''} fill="none"/>`).join('')}${Array.from({length:7},(_,x)=>`<circle cx="${X(x)}" cy="${Y(linearValue(m,x))}" r="3" fill="#245d6b"/>`).join('')}<circle cx="${X(w.x)}" cy="${Y(linearValue(m,w.x))}" r="7" fill="#f0c974" stroke="#294e54" stroke-width="2"/></svg><figcaption>Solid: ${esc(m.title)}.${partner?` Dashed: ${esc(partner.title)}.`:''} Lines connect the pictured points in this invented model. The table gives exact values.</figcaption></figure>`;}
function table(w){const m=w.source.model,p=m.comparison?{...m,...m.comparison}:null;return `<div class="linear-table"><table><caption>Reference model · x in ${esc(m.xUnit)}, y in ${esc(m.yUnit)}</caption><thead><tr><th scope="col">x</th><th scope="col">${p?'Solid line y':'y'}</th>${p?'<th scope="col">Dashed line y</th>':''}</tr></thead><tbody>${Array.from({length:7},(_,x)=>`<tr${x===w.x?' class="linear-current"':''}><th scope="row">${x}</th><td>${formatLinearNumber(linearValue(m,x))}</td>${p?`<td>${formatLinearNumber(linearValue(p,x))}</td>`:''}</tr>`).join('')}</tbody></table></div>`;}
function bridge(w){if(!w.source.bridge)return '';const halves=w.source.bridge==='halves',values=halves?Array.from({length:9},(_,n)=>parseLinearNumber(`${n}/2`)):Array.from({length:15},(_,n)=>({n:n-6,d:1})),current=linearValue(w.source.model,w.x),X=q=>halves?20+q.n/q.d*76:20+(q.n/q.d+6)*22;return `<aside class="linear-numberline"><h3>${halves?'Two halves make a whole':'Zero is the reference platform'}</h3><svg viewBox="0 0 350 100" role="img" aria-label="${halves?'Half-unit ticks from 0 to 4':'Signed number line from minus 6 to 8'}. Current relative height ${formatLinearNumber(current)}."><path d="M20 40H330" stroke="#294e54" stroke-width="2"/>${values.map(q=>`<path d="M${X(q)} 33V47" stroke="#294e54"/>${halves||q.n%2===0?`<text x="${X(q)}" y="68" text-anchor="middle">${formatLinearNumber(q)}</text>`:''}`).join('')}<circle cx="${X(current)}" cy="40" r="7" fill="#f0c974" stroke="#294e54" stroke-width="2"/><text x="175" y="92" text-anchor="middle">Current height: ${formatLinearNumber(current)}</text></svg><p>${halves?'0 → 1/2 → 1: two equal half-steps make one whole.':'Left of zero is below the platform; right of zero is above it. Moving down through zero continues into negative heights.'}</p></aside>`;}
function reference(w){const m=w.source.model;return `<aside class="linear-reference" aria-labelledby="linear-reference"><h2 id="linear-reference" tabindex="-1">Reference model</h2>${btn('data-linear-back-to-page aria-controls="linear-turn"','Back to this page')}<p>${esc(m.title)}</p><div class="linear-stepper">${btn(`data-linear-delta="-1" aria-label="Decrease input by one" aria-disabled="${w.x===0}"`,'−')}<label>Input x · ${esc(m.xUnit)}<select data-linear-x>${Array.from({length:7},(_,n)=>`<option${w.x===n?' selected':''}>${n}</option>`).join('')}</select></label>${btn(`data-linear-delta="1" aria-label="Increase input by one" aria-disabled="${w.x===6}"`,'+')}</div><p class="linear-value">x = ${w.x} ${esc(m.xUnit)} → y = ${formatLinearNumber(linearValue(m,w.x))} ${esc(m.yUnit)}</p>${bridge(w)}${graph(w)}${table(w)}</aside>`;}
function task(w,i){const last=w.checks.filter(c=>c.item.id===i.id).at(-1),help=w.help[i.id]||[];return `<article class="linear-item" id="linear-item-${esc(i.id)}" tabindex="-1"><h3>${esc(i.prompt)}</h3>${i.guidance.length?`<ol class="linear-guidance">${i.guidance.map(t=>`<li>${esc(t)}</li>`).join('')}</ol>`:''}<p class="linear-syntax">Type a signed number, decimal, or fraction such as -3/2. Use a positive denominator and type a minus with the - key. These are supported practice responses.</p>${i.fields.map(f=>`<label>${esc(f.label)}<input type="text" inputmode="text" autocomplete="off" spellcheck="false" maxlength="40" data-linear-item="${esc(i.id)}" data-linear-field="${esc(f.id)}" value="${esc(w.drafts[i.id]?.[f.id]||'')}"></label>`).join('')}<div class="linear-actions">${btn(`data-linear-check="${esc(i.id)}"`,'Check these values',true)}${btn(`data-linear-help="${esc(i.id)}" data-help-kind="hint"`,'Hint')}${btn(`data-linear-help="${esc(i.id)}" data-help-kind="example"`,'Different example')}${btn(`data-linear-skip="${esc(i.id)}"`,'Skip for now')}</div>${help.includes('hint')?`<aside class="linear-help" id="linear-help-${esc(i.id)}-hint" tabindex="-1"><strong>Hint</strong><p>${esc(i.hint)}</p></aside>`:''}${help.includes('example')?`<aside class="linear-help" id="linear-help-${esc(i.id)}-example" tabindex="-1"><strong>A different worked example</strong><p>${esc(i.example)}</p></aside>`:''}${last?`<aside class="linear-feedback" id="linear-feedback-${esc(i.id)}" tabindex="-1"><strong>Last check: ${Object.values(last.raw).map(esc).join(', ')}</strong><p>${esc(last.feedback)}</p></aside>`:''}<p id="linear-input-status-${esc(i.id)}" tabindex="-1"></p>${w.skips.some(k=>k.itemId===i.id)?'<p>Skipped for now. You can return to these fields whenever useful.</p>':''}</article>`;}
const recommendationLabel=code=>code?(linearRecommendations.find(([value])=>value===code)?.[1]||`Saved choice: ${code}`):'None';
function turn(w){const s=w.source;return `<section class="linear-turn"><h2 id="linear-turn" tabindex="-1">${esc(w.page===0?s.title:linearPages[w.page])}</h2>${w.page===0?`<p class="linear-idea">${esc(s.idea)}</p>${s.teach.map(t=>`<p>${esc(t)}</p>`).join('')}<p>Try changing x in the reference model. The table, graph point and exact output move together.</p>`:`${w.page===3?`<p class="linear-context">${s.generation?'Use the rules and quantities in this question. The reference table and graph stay available as support.':'The question below introduces a new context. The reference graph and table retain this lesson’s earlier model; use the new rule stated in the question.'}</p>`:''}${s.items.filter(i=>i.page===w.page).map(i=>task(w,i)).join('')}`}${w.page===3?`<label>Your explanation, question, or next example (optional; human-read)<textarea data-linear-note maxlength="1200" rows="4">
${esc(w.note)}</textarea></label>${s.id==='carry'?`<label>A next step you would like (optional and ungraded)<select data-linear-recommendation>${!linearRecommendations.some(([v])=>v===w.recommendation)?`<option value="${esc(w.recommendation)}" selected>${esc(recommendationLabel(w.recommendation))}</option>`:''}${linearRecommendations.map(([v,t])=>`<option value="${v}"${w.recommendation===v?' selected':''}>${esc(t)}</option>`).join('')}</select></label>`:''}${btn('data-linear-keep','Keep this visit',true)}${w.kept?'<p>Visit kept. Its first version is retained too. All lessons are still open.</p>':''}`:''}</section>`;}

function exploration(state){const s=linearSuggestion(state),visits=linearGeneratedVisits(state);return `<section class="linear-exploration" aria-labelledby="linear-exploration"><h2 id="linear-exploration">Another investigation</h2><p>${esc(s.reason)}</p><p>Suggestions use first responses from different cases, keeping optional support separate. These remain supported practice. Choose any question type. New accounts can rise, stay steady or fall. Saved visits keep their original rules. Quantities change within a bounded set and can recur on later visits.</p><label>Choose a question type<select data-linear-challenge>${linearChallenges.map(([c,t])=>`<option value="${c}"${c===s.challenge?' selected':''}>${esc(t)}</option>`).join('')}</select></label>${s.canCreate?btn('data-linear-create','Open another investigation',true):'<p>New investigations cannot be created from the saved selection metadata or its exhausted counter. Existing work remains available.</p>'}<p><a href="#notes">Download your notes</a> to keep a copy of your work.</p>${visits.length?`<label>Saved generated visit to remove (optional)<select data-linear-remove-choice><option value="">Choose a generated visit</option>${visits.map(v=>`<option value="${esc(v.id)}">${esc(v.title)}</option>`).join('')}</select></label>${btn('data-linear-remove','Remove selected generated visit')}<p>Removal asks for confirmation and removes that visit’s drafts, explanation and first/latest kept writing. Fixed lessons stay available.</p>`:''}</section>`;}

export function linearRefusal(){return '<section class="linear-page" data-linear-root><h1 id="linear-turn" tabindex="-1">Signed rates and linear equations</h1><p>This page could not be shown while keeping your notebook exportable. Earlier work is unchanged.</p><a href="#notes">Download your notes</a><a href="#pathways">Choose another subject</a></section>';}
export function linearPage(state,requestedId=''){
 const v=linearView(state),w=v.work,requested=linearLessons.find(s=>s.id===requestedId)||(validLinearWork(state.linearPathway?.lessons?.[requestedId])?state.linearPathway.lessons[requestedId].source:null),preview=requested&&(!w||state.linearPathway.currentId!==requestedId);
 const choices=v.status==='unavailable'?'':`<details class="linear-choices" data-linear-choices ${!w&&!preview?'open':''}><summary><span class="linear-choice-marker" aria-hidden="true"></span>Choose another lesson or investigation</summary>${exploration(state)}<nav class="linear-lessons" aria-label="Open math lessons">${v.lessons.map(c=>c.unreadable?`<p>Earlier ${esc(c.title)} work is retained; this lesson cannot be edited here.</p>`:btn(`data-linear-start="${esc(c.id)}" aria-pressed="${state.linearPathway?.currentId===c.id&&!!w}"`,c.title)).join('')}</nav><p>A fitting answer describes this supplied task; it does not set a level.</p><a href="#desk/linear">Revisit the Courier’s Price</a></details>`;
 const content=v.status==='unavailable'?'<h2 id="linear-turn" tabindex="-1">Your earlier format is retained</h2><p>Other subjects and notes are open. This version cannot edit that format.</p><a href="#notes">Open notes</a>':preview?`<section class="linear-turn"><h2 id="linear-turn" tabindex="-1">${esc(requested.title)}</h2><p>${esc(requested.idea)}</p><p>Choose Start or continue to open this lesson. Any earlier work elsewhere will be waiting.</p>${v.lessons.find(s=>s.id===requestedId)?.unreadable?'<p>This earlier lesson is retained but cannot be edited here.</p>':btn(`data-linear-start="${esc(requested.id)}"`,'Start or continue this lesson',true)}</section>`:w?`<nav class="linear-pages" aria-label="Lesson pages">${linearPages.map((p,n)=>btn(`data-linear-page="${n}" aria-current="${w.page===n?'step':'false'}"`,`${n+1}. ${p}`,w.page===n)).join('')}</nav><div class="linear-model-jump">${btn('data-linear-see-model aria-controls="linear-reference"','See reference model')}</div><div class="linear-layout">${turn(w)}${reference(w)}</div><nav class="linear-actions" aria-label="Previous and next page">${w.page>0?btn(`data-linear-page="${w.page-1}"`,'Previous page'):''}${w.page<3?btn(`data-linear-page="${w.page+1}"`,'Next page',true):''}</nav><p>Visited pages: ${w.visited.map(n=>linearPages[n]).join(', ')}. Visits are a navigation record, not a score.</p>`:'<h2 id="linear-turn" tabindex="-1">Choose any lesson to begin</h2><p>The lesson cards are all open. No earlier result is required.</p>';
 return `<div class="linear-page" data-linear-root data-linear-visit="${esc(w?state.linearPathway.currentId:'')}" lang="en"><header><a class="back" href="#pathways">Back to subjects</a><h1>Signed rates and linear equations</h1><p>Try an idea, use help, or choose another lesson whenever you like.</p></header>${content}<p id="linear-status" role="status" aria-live="polite" tabindex="-1"></p>${choices}<footer><a href="#learn/math/paired">Paired points</a><a href="#notes">Grown-up notes</a><a href="#pathways">Other subjects</a><a href="#learn/math/equality">When do two rules agree?</a><a href="#desk">The Keeper’s Desk</a></footer></div>`;
}

export function linearNotes(state){if(!Object.hasOwn(state,'linearPathway'))return '';const v=linearView(state);return `<details class="panel"><summary>Signed rates and linear equations · supported practice</summary><p>Shown models, tables and teaching support all responses. Optional hints/examples, raw answers, per-item first checks, up to 24 checks and skips (further records refuse without dropping earlier work) and first/latest kept visits are retained. These do not establish independent fluency, mastery or course completion. Writing and self-selected next steps are ungraded.</p>${v.status==='unavailable'?'<p>Earlier format retained unchanged.</p>':v.lessons.map(c=>{const w=state.linearPathway.lessons[c.id];return w?`<h3>${esc(c.title)}</h3>${c.unreadable?'<p>Earlier lesson retained unchanged.</p>':`<p>${w.checks.length} recent checks; ${w.skips.length} recent skips; kept visit: ${w.kept?'yes':'not yet'}. Next step chosen: ${esc(recommendationLabel(w.recommendation))}.</p>`}`:'';}).join('')}<details><summary>Frozen sources, exact drafts and kept versions</summary><pre>${esc(JSON.stringify(state.linearPathway,null,2))}</pre></details></details>`;}
let linearLeaveGuard;
export function bindLinear(state,{save,render,focus,canExport,explorerId,isActive}){linearLeaveGuard?.abort();linearLeaveGuard=new AbortController();const root=document.querySelector('[data-linear-root]');if(!root)return;const owner=explorerId?.(),route=location.hash,visit=root.dataset.linearVisit,o={canExport},dirty=new Set();const live=el=>root.isConnected&&el.isConnected&&root.contains(el)&&location.hash===route&&(!isActive||isActive())&&explorerId?.()===owner&&!el.closest('details:not([open])');const say=(t,take=true)=>{const el=document.querySelector('#linear-status');if(el){el.textContent=t;if(take)el.focus();}};const fail=()=>say('This change could not be kept safely. Earlier work is unchanged. Download your notes. If space or a visit’s record limit is reached, open “Choose another lesson or investigation” below to remove a selected generated visit or open another investigation.');const redraw=(t='',target='#linear-turn',forceChoices=false)=>{
 const choices=root.querySelector('[data-linear-choices]'),challenge=root.querySelector('[data-linear-challenge]'),remove=root.querySelector('[data-linear-remove-choice]'),shown=choices?.open,chosen=challenge?.dataset.linearChosen==='true',kind=challenge?.value,removal=remove?.value;
 stopSpeech();save();render();const next=document.querySelector('[data-linear-root]');
 if(next&&location.hash===route&&explorerId?.()===owner&&(!isActive||isActive())){
  const same=next.dataset.linearVisit===visit,d=next.querySelector('[data-linear-choices]');if(d&&(same||forceChoices))d.open=forceChoices||!!shown;
  if(same){const c=next.querySelector('[data-linear-challenge]'),r=next.querySelector('[data-linear-remove-choice]');if(chosen&&c&&[...c.options].some(x=>x.value===kind)){c.value=kind;c.dataset.linearChosen='true';}if(r&&[...r.options].some(x=>x.value===removal))r.value=removal;}
 }
 if(t){const el=document.querySelector('#linear-status');if(el)el.textContent=t;}focus?.(target);
};const unsaved=(take=true)=>{say('Your visible words have not been saved. Edit the indicated field to try again, or copy those words and restore the last saved words before leaving. Earlier saved work is unchanged.',take);const status=root.querySelector('#linear-status'),b=document.createElement('button');b.type='button';b.className='secondary';b.dataset.linearDiscard='';b.textContent='Restore last saved words';b.addEventListener('click',()=>{if(!live(b)||!window.confirm('Discard the visible unsaved edits and restore this page’s last saved words? Earlier saved work stays unchanged.'))return;dirty.clear();redraw('Last saved words restored. You can download notes or choose another investigation.','#linear-status');});status?.append(b);};const clicks=(sel,fn)=>root.querySelectorAll(sel).forEach(el=>el.addEventListener('click',()=>{if(!live(el))return;if(dirty.size)return unsaved();fn(el);}));
 root.querySelector('[data-linear-challenge]')?.addEventListener('change',e=>{if(live(e.target))e.target.dataset.linearChosen='true';});
 for(const [selector,target]of [['[data-linear-see-model]','#linear-reference'],['[data-linear-back-to-page]','#linear-turn']])root.querySelector(selector)?.addEventListener('click',e=>{if(live(e.currentTarget))focus?.(target);});
 clicks('[data-linear-start]',b=>{if(!startLinear(state,b.dataset.linearStart,o))return fail();const next=`#learn/math/${b.dataset.linearStart}`;if(location.hash===next)return redraw();stopSpeech();save();window.addEventListener('hashchange',()=>{if(location.hash===next&&(!isActive||isActive())&&explorerId?.()===owner)focus?.('#linear-turn');},{once:true});location.hash=next;});
 clicks('[data-linear-create]',()=>{const challenge=root.querySelector('[data-linear-challenge]')?.value,key=createLinearInvestigation(state,challenge,o);if(!key)return fail();const next=`#learn/math/${key}`;stopSpeech();save();window.addEventListener('hashchange',()=>{if(location.hash===next&&(!isActive||isActive())&&explorerId?.()===owner)focus?.('#linear-turn');},{once:true});location.hash=next;});
 clicks('[data-linear-remove]',()=>{const key=root.querySelector('[data-linear-remove-choice]')?.value,v=linearGeneratedVisits(state).find(v=>v.id===key);if(!v)return say('Choose the generated visit you want to remove.');if(!window.confirm(`Remove ${v.title}? Its frozen source, drafts, original explanation and first/latest kept writing will be removed. Download your notes first if you want a copy.`))return;if(!live(root))return;if(!removeLinearInvestigation(state,key,true,o))return fail();redraw('Selected generated visit removed. Other work is still available.','#linear-exploration',true);});
 clicks('[data-linear-page]',b=>setLinearPage(state,Number(b.dataset.linearPage),o)?redraw():fail());
 clicks('[data-linear-delta]',b=>{const w=linearView(state).work,n=w.x+Number(b.dataset.linearDelta);if(n<0||n>6)return say('This reference model uses inputs from 0 to 6.',false);if(!setLinearX(state,n,o))return fail();redraw(`Input ${n}; output ${formatLinearNumber(linearValue(w.source.model,n))}.`,`[data-linear-delta="${b.dataset.linearDelta}"]`);});
 root.querySelector('[data-linear-x]')?.addEventListener('change',e=>{if(!live(e.target))return;if(dirty.size){e.target.value=linearView(state).work.x;return unsaved();}if(!setLinearX(state,Number(e.target.value),o))return fail();redraw('Reference model updated.','[data-linear-x]');});
 root.querySelectorAll('[data-linear-field]').forEach(el=>el.addEventListener('input',()=>{if(!live(el))return;const key=`${el.dataset.linearItem}/${el.dataset.linearField}`;if(!setLinearField(state,el.dataset.linearItem,el.dataset.linearField,el.value,o)){dirty.add(key);el.setAttribute('aria-invalid','true');return unsaved(false);}dirty.delete(key);el.removeAttribute('aria-invalid');save();}));
 root.querySelector('[data-linear-note]')?.addEventListener('input',e=>{if(!live(e.target))return;if(!setLinearNote(state,e.target.value,o)){dirty.add('note');e.target.setAttribute('aria-invalid','true');return unsaved(false);}dirty.delete('note');e.target.removeAttribute('aria-invalid');save();});
 root.querySelector('[data-linear-recommendation]')?.addEventListener('change',e=>{if(!live(e.target))return;if(!setLinearRecommendation(state,e.target.value,o))return fail();save();say('Your next-step choice is kept; all lessons remain open.',false);});
 clicks('[data-linear-help]',b=>showLinearHelp(state,b.dataset.linearHelp,b.dataset.helpKind,o)?redraw('Support opened.',`#linear-help-${b.dataset.linearHelp}-${b.dataset.helpKind}`):fail());
 clicks('[data-linear-check]',b=>{if(linearView(state).work?.checks.length>=24)return say('This visit already retains 24 checks. Earlier checks and writing stay unchanged. Open “Choose another lesson or investigation” below to keep practicing, or download notes and explicitly remove a selected generated visit.');const r=checkLinear(state,b.dataset.linearCheck,o);if(!r)return fail();if(!r.recorded){say(r.feedback,false);const local=root.querySelector(`#linear-input-status-${b.dataset.linearCheck}`);if(local){local.textContent=r.feedback;local.focus();}return;}redraw(r.feedback,`#linear-feedback-${b.dataset.linearCheck}`);});
 clicks('[data-linear-skip]',b=>{if(linearView(state).work?.skips.length>=24)return say('This visit already retains 24 skips. Earlier records stay unchanged. Open “Choose another lesson or investigation” below, or return to any existing question.');return skipLinear(state,b.dataset.linearSkip,o)?redraw('Skipped for now. Choose another page or return whenever useful.',`#linear-item-${b.dataset.linearSkip}`):fail();});
 clicks('[data-linear-keep]',()=>keepLinear(state,o)?redraw('Visit kept. Its first version stays available in notes.','#linear-status'):fail());
 document.addEventListener('click',e=>{if(!dirty.size||!root.isConnected||root.contains(e.target))return;if(e.target.closest('button,a,input,select,summary')){e.preventDefault();e.stopImmediatePropagation();unsaved();}},{capture:true,signal:linearLeaveGuard.signal});
 root.querySelectorAll('a').forEach(a=>a.addEventListener('click',e=>{if(!live(a)){e.preventDefault();return;}if(dirty.size){e.preventDefault();unsaved();}}));
}
